--DS d_ds_oe_hdr_pick_ticket  - from pick ticket reportSELECT oe_hdr.company_id,oe_hdr.order_no,oe_hdr.carrier_id,oe_hdr.delivery_instructions,oe_hdr.customer_id,oe_hdr.pick_ticket_type,oe_hdr.front_counter,oe_hdr.packing_basis,oe_hdr.freight_code_uid,oe_hdr.invoice_batch_uid,oe_hdr.source_code_no,oe_hdr.order_type,oe_hdr.validation_status,oe_hdr.will_call,carrier.name carrier_name,'Y' create_pick_ticket_flag,oe_hdr.address_id,oe_hdr.ship2_state,oe_hdr.freight_out,oe_hdr.rental_transaction_status_cdFROM oe_hdrLEFT JOIN shipping_route ON shipping_route.shipping_route_uid = oe_hdr.shipping_route_uidLEFT JOIN address carrier ON carrier.id = oe_hdr.carrier_id INNER JOIN system_setting ss1 ON ss1.name = 'process_prod_order_when_hold'INNER JOIN (SELECT	oe_line.order_noFROM	oe_lineINNER JOIN inv_loc ON oe_line.inv_mast_uid = inv_loc.inv_mast_uidAND oe_line.source_loc_id = inv_loc.location_idINNER JOIN oe_hdr ON oe_hdr.order_no = oe_line.order_noLEFT JOIN oe_line_service ON oe_line.oe_line_uid = oe_line_service.oe_line_uidWHERE ('N' = 'N' OR oe_line.inv_mast_uid IN (0))AND	(	oe_line.ship_loc_id = 300 OR(	oe_line.source_loc_id = 300 ANDoe_line.source_loc_id <> oe_line.ship_loc_id ))AND	(	oe_line_service.row_status_flag = 1268 OR(	(	oe_line.required_date BETWEEN {ts '1990-01-01 00:00:00.000'} AND {ts '2020-09-10 23:59:59.000'} OR oe_line.scheduled = 'Y' ) ANDoe_line.cancel_flag <> 'Y' ANDoe_line.other_charge <> 'Y' AND(	oe_line.qty_allocated > 0 OR oe_line.scheduled = 'Y' OR(	(	(	'N' = 'Y' AND oe_line.qty_staged > 0 ) OR(	'N' = 'N' AND(	(	oe_line.disposition = 'C' AND oe_hdr.packing_basis <> 'Partial' ) OR oe_line.qty_staged > 0 ))) OR( 'N' = 'Y' AND(	oe_line.expedite_date >= CAST(CAST(oe_hdr.order_date AS VARCHAR(11)) AS DATETIME) ANDoe_line.expedite_date <= GETDATE() AND ((oe_line.qty_on_pick_tickets = 0 AND 'N' = 'Y') OR 'N' = 'N'))))) AND(	oe_line.will_call = 'N' OR oe_line.will_call = 'N' OR oe_line.lot_bill = 'Y') AND( 'N' = 'N' OR oe_line.scheduled = 'Y' OR COALESCE(oe_line.pick_date, {ts '1900-01-01 00:00:00.000'}) BETWEEN {ts '1900-01-01 00:00:00.000'} AND {ts '1900-01-01 00:00:00.000'})))AND oe_line.complete = 'N'GROUP BY oe_line.order_no) AS drv_pickable_lines ON drv_pickable_lines.order_no = oe_hdr.order_noWHERE oe_hdr.customer_id BETWEEN 0 AND 999999999AND	oe_hdr.address_id BETWEEN 0 AND 999999999AND	oe_hdr.order_no BETWEEN '0' AND '99999999'AND	COALESCE(oe_hdr.ship2_zip, ' ') BETWEEN ' ' AND 'ZZZZZZZZZZ'AND	oe_hdr.order_date BETWEEN {ts '1990-01-01 00:00:00.000'} AND {ts '2020-09-10 23:59:59.000'}AND	oe_hdr.date_created BETWEEN {ts '1990-01-01 00:00:00.000'} AND {ts '2049-12-31 00:00:00.000'}AND	oe_hdr.date_last_modified BETWEEN {ts '1990-01-01 00:00:00.000'} AND {ts '2049-12-31 00:00:00.000'}AND	oe_hdr.last_maintained_by BETWEEN ' ' AND 'ZZZZZZZ'AND	COALESCE(oe_hdr.po_no, ' ') BETWEEN ' ' AND 'ZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZ' AND( ( 'Y' = 'O' AND COALESCE(oe_hdr.order_type, 0) = 1706 ) OR( 'Y' = 'N' AND COALESCE(oe_hdr.order_type, 0) <> 1706 ) OR( 'Y' = 'Y' ))AND	oe_hdr.approved = 'Y'AND	oe_hdr.cancel_flag = 'N'AND	oe_hdr.completed = 'N'AND	oe_hdr.projected_order = 'N'AND	(oe_hdr.validation_status <> 'Hold' OR ss1.value = 'Y')AND	oe_hdr.rma_flag = 'N'AND	(oe_hdr.carrier_id IS NULL OR NULL IS NULL)AND	((oe_hdr.routed_eta_date BETWEEN NULL AND NULL) OR oe_hdr.routed_eta_date IS NULL)AND	COALESCE(shipping_route.route_code, '') BETWEEN ' ' AND 'ZZZZZ'AND COALESCE(carrier.name, '') BETWEEN ' ' AND 'ZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZ'ORDER BY oe_hdr.order_no ASC,oe_hdr.ship2_zip ASC, oe_hdr.customer_id ASC, oe_hdr.order_date ASC